// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    // fuzz the calleeSelector so the fuzzer can vary calldata; we also fuzz a uint256 sentinel
    function testFuzz_property(bytes calldata calldat, uint256 sentinel) public {
        // Keep inputs wide; no tight assumptions
        // Deploy a reverting helper that always reverts on any call
        Reverter rev = new Reverter();

        // Try calling c.forward to the reverting callee. The reference implementation should revert,
        // while the mutant (require(true)) will not revert. We observe this via try/catch.
        bool ok;
        try c.forward(address(rev), calldat) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): for ANY calldata and sentinel, calling forward
        // to a callee that reverts must cause forward to revert (ok == false).
        // The buggy mutant that ignores the call result will violate this for some inputs
        // (it will set ok == true); so this assert distinguishes them.
        assertTrue(!ok);
    }
}

contract Reverter {
    // Reject any incoming call by reverting
    fallback() external payable {
        revert("revert from helper");
    }
    receive() external payable { revert("revert receive"); }
}
